package com.tns.day2;

public class IfDemo {

	public static void main(String[] args) {
		
		// TODO Auto-generated method stub
        int x = 5;
        if (x!= 5)// condition false 
        System.out.println("value of x is not 5");
        System.out.println("value of x is  5");
        System.out.println("value is 5");// 2nd only print
        
        int y = 5;
        if (y== 5)// condition true
        System.out.println("value of y is not 5");
        System.out.println("value of y is  5");// both print
	}

}
